"""Fault-inject initial intake latency, not synchronization or a production change."""
import asyncio,sys
from pathlib import Path
repo=Path.cwd()
for p in [repo,repo/'services/runtime/src',repo/'packages/protocol-python/src',repo/'packages/model-worker-sdk-python/src',repo/'services/runtime/tests']:sys.path.insert(0,str(p))
import pytest
from chatwaifu_runtime.external_channels.management import ChannelManagementService
class InitialIntakeLatency:
 @pytest.hookimpl(hookwrapper=True)
 def pytest_runtest_call(self,item):
  original=ChannelManagementService._remember_context
  async def slow(self,connection_id,external_message_id,context):
   if external_message_id in {f'pressure-{i}' for i in range(4)}:
    await asyncio.sleep(1.5)
   return await original(self,connection_id,external_message_id,context)
  ChannelManagementService._remember_context=slow
  try:yield
  finally:ChannelManagementService._remember_context=original
sys.exit(pytest.main(['services/runtime/tests/test_inbound_multi_image_burst.py::test_full_deferred_burst_and_many_more_images_do_not_block_stop[False]','-q','--tb=short'],plugins=[InitialIntakeLatency()]))

"""Suppress dispatch in memory; revised readiness check must still fail."""
import asyncio
import sys
from pathlib import Path
repo = Path.cwd()
for path in (repo, repo / 'services/runtime/src', repo / 'packages/protocol-python/src', repo / 'packages/model-worker-sdk-python/src', repo / 'services/runtime/tests'):
    sys.path.insert(0, str(path))
import pytest
from chatwaifu_runtime.external_channels.burst import ImageBurstCoordinator
class SuppressedDispatch:
    @pytest.hookimpl(hookwrapper=True)
    def pytest_runtest_call(self, item):
        original = ImageBurstCoordinator._spawn_dispatch_task
        def suppress(self, batch):
            async def no_dispatch():
                return None
            return asyncio.create_task(no_dispatch())
        ImageBurstCoordinator._spawn_dispatch_task = suppress
        try:
            yield
        finally:
            ImageBurstCoordinator._spawn_dispatch_task = original
sys.exit(pytest.main(['services/runtime/tests/test_inbound_multi_image_burst.py::test_full_deferred_burst_and_many_more_images_do_not_block_stop[False]', '-q', '--tb=short'], plugins=[SuppressedDispatch()]))
